/**
 * Syndicate devnet E2E test — run from services/settlement-chain/:
 *   cd services/settlement-chain && node ../../scripts/e2e-devnet-test.ts
 *
 * Required env vars:
 *   BASIC_AUTH         dev:yourpassword   (nginx HTTP Basic Auth for all deployed endpoints)
 *   PLAYER2_KEYPAIR    /tmp/player2.json  (generated by solana-keygen new; defaults to /tmp/player2.json)
 *
 * Optional overrides:
 *   MATCHMAKING_URL    https://matchmaking.devnet.satoshitable.fun  (after nginx deploy)
 *   GATEWAY_URL        wss://gateway.devnet.satoshitable.fun
 *   PROGRAM_ID         GhbHLYTHuSvCVhYM22wyjdoE6Nx5uQDNuBB2Wof4p2bF
 *   CHIPS_TOKEN_MINT   3Gdd9ew2Dq63QeJETc7krKB2JJ1GaHfBZvMzBdAy541X  (user's test token)
 *   SOLANA_RPC_URL     https://api.devnet.solana.com
 *   BUY_IN             1000000   (raw token units; default = 1 USDC with 6 decimals)
 */

import {
  Connection,
  Keypair,
  PublicKey,
  SystemProgram,
  SYSVAR_RENT_PUBKEY,
  Transaction,
  sendAndConfirmTransaction,
} from '@solana/web3.js';
import { getAssociatedTokenAddressSync, TOKEN_PROGRAM_ID } from '@solana/spl-token';
import { createHash, createPrivateKey, randomBytes, sign as cryptoSign } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { homedir } from 'node:os';

// ─── config ─────────────────────────────────────────────────────────────────

const RPC_URL = process.env.SOLANA_RPC_URL ?? 'https://api.devnet.solana.com';
const MATCHMAKING_URL =
  process.env.MATCHMAKING_URL ?? 'https://matchmaking.devnet.satoshitable.fun';
const GATEWAY_URL =
  process.env.GATEWAY_URL ?? 'wss://gateway.devnet.satoshitable.fun';
const PROGRAM_ID = new PublicKey(
  process.env.SYNDICATE_PROGRAM_ID ?? 'GhbHLYTHuSvCVhYM22wyjdoE6Nx5uQDNuBB2Wof4p2bF',
);
const CHIPS_MINT = new PublicKey(
  process.env.CHIPS_TOKEN_MINT ?? '3Gdd9ew2Dq63QeJETc7krKB2JJ1GaHfBZvMzBdAy541X',
);
const BASIC_AUTH = process.env.BASIC_AUTH; // e.g. "dev:devpassword"
const PLAYER1_PATH = process.env.PLAYER1_KEYPAIR ?? `${homedir()}/.config/solana/id.json`;
const PLAYER2_PATH = process.env.PLAYER2_KEYPAIR ?? '/tmp/player2.json';
const BUY_IN = BigInt(process.env.BUY_IN ?? '1000000'); // 1 USDC (6 decimals)

// BTC/USD tier-standard config hash (pre-computed from config service buildTemplates())
const CONFIG_HASH =
  '852148f8f4b6f703f6e3b7357fac28860f4169b5110660f14a507d41c17d939b';
// BTC/USD price token (Ethereum address, 20 bytes)
const FEED_TOKEN_HEX = 'a7BaE7da3E4950700BE9f107EB186e89a474d180';

// ─── helpers ────────────────────────────────────────────────────────────────

function loadKeypair(path: string): Keypair {
  const bytes = JSON.parse(readFileSync(path, 'utf8')) as number[];
  return Keypair.fromSecretKey(Uint8Array.from(bytes));
}

function log(msg: string) { console.log(`[${new Date().toISOString()}] ${msg}`); }
function ok(label: string) { log(`✓ ${label}`); }
function fail(label: string, detail?: unknown): never {
  console.error(`✗ ${label}`, detail ?? '');
  process.exit(1);
}

function authHeaders(): Record<string, string> {
  if (!BASIC_AUTH) return {};
  return { Authorization: `Basic ${Buffer.from(BASIC_AUTH).toString('base64')}` };
}

async function apiGet(url: string): Promise<unknown> {
  const r = await fetch(url, { headers: authHeaders() });
  if (!r.ok) throw new Error(`GET ${url} → ${r.status} ${await r.text()}`);
  return r.json();
}

async function apiPost(url: string, body: unknown): Promise<unknown> {
  const r = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...authHeaders() },
    body: JSON.stringify(body),
  });
  const text = await r.text();
  let json: unknown;
  try { json = JSON.parse(text); } catch { json = text; }
  return json;
}

// ─── Borsh-lite encoding ─────────────────────────────────────────────────────

function u8(n: number): Buffer { const b = Buffer.alloc(1); b.writeUInt8(n); return b; }
function u16(n: number): Buffer { const b = Buffer.alloc(2); b.writeUInt16LE(n); return b; }
function u32(n: number): Buffer { const b = Buffer.alloc(4); b.writeUInt32LE(n); return b; }
function i32(n: number): Buffer { const b = Buffer.alloc(4); b.writeInt32LE(n); return b; }
function u64(n: bigint): Buffer {
  const b = Buffer.alloc(8);
  b.writeBigUInt64LE(n);
  return b;
}

function anchorDiscriminator(name: string): Buffer {
  return createHash('sha256')
    .update(name)
    .digest()
    .slice(0, 8);
}

// ─── PDA derivation ──────────────────────────────────────────────────────────

function deriveMatchPdas(onchainMatchId: bigint) {
  const matchSeed = u64(onchainMatchId);
  const [matchPda] = PublicKey.findProgramAddressSync(
    [Buffer.from('match'), matchSeed],
    PROGRAM_ID,
  );
  const [vault] = PublicKey.findProgramAddressSync(
    [Buffer.from('vault'), matchPda.toBuffer()],
    PROGRAM_ID,
  );
  const [protocol] = PublicKey.findProgramAddressSync(
    [Buffer.from('protocol')],
    PROGRAM_ID,
  );
  return { matchPda, vault, protocol };
}

function deriveSeatPda(matchPda: PublicKey, player: PublicKey): PublicKey {
  const [seat] = PublicKey.findProgramAddressSync(
    [Buffer.from('seat'), matchPda.toBuffer(), player.toBuffer()],
    PROGRAM_ID,
  );
  return seat;
}

function deriveSeatIndexPda(matchPda: PublicKey, seatIndex: number): PublicKey {
  const [si] = PublicKey.findProgramAddressSync(
    [Buffer.from('seat-index'), matchPda.toBuffer(), u16(seatIndex)],
    PROGRAM_ID,
  );
  return si;
}

// ─── CreateParams encoding ───────────────────────────────────────────────────

function encodeCreateParams(onchainMatchId: bigint, fillWindowSec = 120n): Buffer {
  const buyIn = BUY_IN;
  const entryFee = 0n;
  const rakeBps = 300;
  const rakeCap = buyIn;
  const nonsealPenaltyBps = 2500;
  const minPlayers = 2;
  const maxPlayers = 5;
  const totalBettingDurationSec = 580n;
  const sealWindow = 20n;
  const beginLiveWindow = 5n;
  const maxOracleConfidence = (1n << 64n) - 1n;
  const oracleExponent = -18;

  const configHashBuf = Buffer.from(CONFIG_HASH, 'hex');
  const feedTokenBuf = Buffer.from(FEED_TOKEN_HEX, 'hex');

  return Buffer.concat([
    u64(onchainMatchId),
    u64(buyIn),
    u64(entryFee),
    u32(rakeBps),
    u64(rakeCap),
    u32(nonsealPenaltyBps),
    u8(minPlayers),
    u8(maxPlayers),
    configHashBuf,       // 32 bytes
    feedTokenBuf,        // 20 bytes
    u64(totalBettingDurationSec),
    u64(sealWindow),
    u64(beginLiveWindow),
    u64(fillWindowSec),
    u64(maxOracleConfidence),
    i32(oracleExponent),
  ]);
}

// ─── Instruction builders ────────────────────────────────────────────────────

function buildCreateAndDeposit(
  player: PublicKey,
  pdas: ReturnType<typeof deriveMatchPdas>,
  playerToken: PublicKey,
  seat: PublicKey,
  seatIndex: PublicKey,
  params: Buffer,
  seatIdx: number,
) {
  const disc = anchorDiscriminator('global:create_and_deposit');
  return {
    programId: PROGRAM_ID,
    keys: [
      { pubkey: player, isSigner: true, isWritable: true },
      { pubkey: pdas.protocol, isSigner: false, isWritable: false },
      { pubkey: CHIPS_MINT, isSigner: false, isWritable: false },
      { pubkey: pdas.matchPda, isSigner: false, isWritable: true },
      { pubkey: pdas.vault, isSigner: false, isWritable: true },
      { pubkey: seat, isSigner: false, isWritable: true },
      { pubkey: seatIndex, isSigner: false, isWritable: true },
      { pubkey: playerToken, isSigner: false, isWritable: true },
      { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
      { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
      { pubkey: SYSVAR_RENT_PUBKEY, isSigner: false, isWritable: false },
    ],
    data: Buffer.concat([disc, params, u16(seatIdx)]),
  };
}

function buildDeposit(
  player: PublicKey,
  protocol: PublicKey,
  matchPda: PublicKey,
  seat: PublicKey,
  seatIndex: PublicKey,
  playerToken: PublicKey,
  vault: PublicKey,
  seatIdx: number,
) {
  const disc = anchorDiscriminator('global:deposit');
  return {
    programId: PROGRAM_ID,
    keys: [
      { pubkey: player, isSigner: true, isWritable: true },
      { pubkey: protocol, isSigner: false, isWritable: false },
      { pubkey: matchPda, isSigner: false, isWritable: true },
      { pubkey: seat, isSigner: false, isWritable: true },
      { pubkey: seatIndex, isSigner: false, isWritable: true },
      { pubkey: playerToken, isSigner: false, isWritable: true },
      { pubkey: vault, isSigner: false, isWritable: true },
      { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
      { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
    ],
    data: Buffer.concat([disc, u16(seatIdx)]),
  };
}

// ─── WebSocket gateway auth test ─────────────────────────────────────────────

type ServerMsg = { type: string; nonce?: string; wallet?: string; reason?: string; serverTime?: number };

function ed25519Sign(secretKey: Uint8Array, message: Buffer): Buffer {
  // secretKey is 64 bytes: seed(32) || publicKey(32)
  const seed = secretKey.slice(0, 32);
  // Ed25519 PKCS#8 v1 DER: 302e020100300506032b657004220420 || seed
  const der = Buffer.concat([
    Buffer.from('302e020100300506032b657004220420', 'hex'),
    Buffer.from(seed),
  ]);
  const privKey = createPrivateKey({ key: der, format: 'der', type: 'pkcs8' });
  return cryptoSign(null, message, privKey) as Buffer;
}

async function testGatewayAuth(keypair: Keypair, label: string): Promise<void> {
  const wsPkg = await import('ws').catch(() => { throw new Error('ws package not found'); });
  const WebSocket = wsPkg.default ?? wsPkg.WebSocket ?? wsPkg;

  return new Promise((resolve, reject) => {
    const headers: Record<string, string> = BASIC_AUTH
      ? { Authorization: `Basic ${Buffer.from(BASIC_AUTH).toString('base64')}` }
      : {};
    const ws = new WebSocket(GATEWAY_URL, { headers });
    const timeout = setTimeout(() => {
      ws.close();
      reject(new Error(`${label}: WS auth timed out`));
    }, 15_000);

    ws.on('message', (data: Buffer) => {
      const msg: ServerMsg = JSON.parse(data.toString());
      if (msg.type === 'challenge' && msg.nonce) {
        const sigBytes = ed25519Sign(keypair.secretKey, Buffer.from(msg.nonce, 'utf-8'));
        const signature = sigBytes.toString('base64');
        ws.send(JSON.stringify({
          type: 'auth',
          wallet: keypair.publicKey.toBase58(),
          signature,
        }));
      } else if (msg.type === 'authenticated') {
        clearTimeout(timeout);
        log(`  ${label}: authenticated as ${msg.wallet}`);
        ws.close();
        resolve();
      } else if (msg.type === 'error') {
        clearTimeout(timeout);
        ws.close();
        reject(new Error(`${label}: gateway error: ${msg.reason}`));
      }
    });
    ws.on('error', (e: Error) => { clearTimeout(timeout); reject(new Error(`${label}: WS error: ${e.message}`)); });
  });
}

// ─── main ────────────────────────────────────────────────────────────────────

async function main() {
  log('=== Syndicate devnet E2E test ===');
  log(`Matchmaking: ${MATCHMAKING_URL}`);
  log(`Gateway:     ${GATEWAY_URL}`);
  log(`Program:     ${PROGRAM_ID.toBase58()}`);
  log(`Chips mint:  ${CHIPS_MINT.toBase58()}`);
  log(`Buy-in:      ${BUY_IN} (raw units)`);
  if (!BASIC_AUTH) log('WARN: BASIC_AUTH not set — calls to nginx-protected endpoints will get 401');

  // ── 1. Load keypairs ──────────────────────────────────────────────────────

  const player1 = loadKeypair(PLAYER1_PATH);
  const player2 = loadKeypair(PLAYER2_PATH);
  log(`Player 1: ${player1.publicKey.toBase58()} (${PLAYER1_PATH})`);
  log(`Player 2: ${player2.publicKey.toBase58()} (${PLAYER2_PATH})`);

  // ── 2. Health checks ──────────────────────────────────────────────────────

  log('\n--- Health checks ---');
  for (const [name, url] of [
    ['matchmaking', `${MATCHMAKING_URL}/healthz`],
    ['config', 'https://config.devnet.satoshitable.fun/healthz'],
    ['action-feed', 'https://api.devnet.satoshitable.fun/healthz'],
    ['price', 'https://price.devnet.satoshitable.fun/health'],
  ] as const) {
    try {
      const data = await apiGet(url as string);
      ok(`${name}: ${JSON.stringify(data).slice(0, 80)}`);
    } catch (e) {
      log(`✗ ${name}: ${(e as Error).message}`);
    }
  }

  // ── 3. Get a valid config template hash from the config service ────────────

  log('\n--- Config templates ---');
  let configHash = CONFIG_HASH;
  try {
    const catalog = await apiGet('https://config.devnet.satoshitable.fun/config/catalog') as any;
    const tiers = catalog?.tiers ?? [];
    log(`  Available tiers: ${tiers.map((t: any) => t.tierId).join(', ')}`);
  } catch {
    log('  (config catalog unavailable — using pre-computed BTC/USD hash)');
  }
  log(`  Using config hash: ${configHash}`);

  // ── 4. RPC connection + balance check ─────────────────────────────────────

  log('\n--- Solana balances ---');
  const conn = new Connection(RPC_URL, 'confirmed');
  const [p1Sol, p2Sol] = await Promise.all([
    conn.getBalance(player1.publicKey),
    conn.getBalance(player2.publicKey),
  ]);
  log(`  Player 1 SOL: ${p1Sol / 1e9}`);
  log(`  Player 2 SOL: ${p2Sol / 1e9}`);

  const p1Token = getAssociatedTokenAddressSync(CHIPS_MINT, player1.publicKey);
  const p2Token = getAssociatedTokenAddressSync(CHIPS_MINT, player2.publicKey);

  const [p1TokInfo, p2TokInfo] = await Promise.all([
    conn.getTokenAccountBalance(p1Token).catch(() => null),
    conn.getTokenAccountBalance(p2Token).catch(() => null),
  ]);
  log(`  Player 1 token: ${p1TokInfo?.value.uiAmountString ?? 'no account'}`);
  log(`  Player 2 token: ${p2TokInfo?.value.uiAmountString ?? 'no account'}`);

  if (!p1TokInfo || !p2TokInfo) {
    fail('Both players need token accounts for the chips mint. Run the setup commands first.');
  }
  const p1Amount = BigInt(p1TokInfo!.value.amount);
  const p2Amount = BigInt(p2TokInfo!.value.amount);
  if (p1Amount < BUY_IN) fail(`Player 1 has ${p1Amount} but needs ${BUY_IN} (buy_in)`);
  if (p2Amount < BUY_IN) fail(`Player 2 has ${p2Amount} but needs ${BUY_IN} (buy_in)`);
  ok(`Both players have sufficient token balance (≥ ${BUY_IN})`);

  // ── 5. create_and_deposit (Player 1 creates the match) ───────────────────

  log('\n--- Step 1: create_and_deposit (Player 1) ---');
  const onchainMatchId = BigInt('0x' + randomBytes(7).toString('hex')); // 56-bit random
  const pdas = deriveMatchPdas(onchainMatchId);
  log(`  onchainMatchId: ${onchainMatchId}`);
  log(`  matchPda:       ${pdas.matchPda.toBase58()}`);
  log(`  vault:          ${pdas.vault.toBase58()}`);
  log(`  protocol:       ${pdas.protocol.toBase58()}`);

  const seatIdx1 = 0;
  const seat1 = deriveSeatPda(pdas.matchPda, player1.publicKey);
  const seatIndex1 = deriveSeatIndexPda(pdas.matchPda, seatIdx1);
  const params = encodeCreateParams(onchainMatchId);

  const createIx = buildCreateAndDeposit(
    player1.publicKey, pdas, p1Token, seat1, seatIndex1, params, seatIdx1,
  );

  const createTx = new Transaction();
  createTx.add(createIx as any);
  createTx.feePayer = player1.publicKey;
  createTx.recentBlockhash = (await conn.getLatestBlockhash()).blockhash;

  log('  Submitting create_and_deposit...');
  let createTxSig: string;
  try {
    createTxSig = await sendAndConfirmTransaction(conn, createTx, [player1], {
      commitment: 'finalized',
      preflightCommitment: 'confirmed',
    });
    ok(`create_and_deposit confirmed: ${createTxSig}`);
  } catch (e) {
    fail('create_and_deposit failed', e);
  }

  // ── 6. Report create txhash to matchmaking ────────────────────────────────

  log('\n--- Step 2: POST /rooms (report create) ---');
  const createReport = await apiPost(`${MATCHMAKING_URL}/rooms`, {
    createTxSig,
    matchPda: pdas.matchPda.toBase58(),
    onchainMatchId: onchainMatchId.toString(),
    configHash,
    wallet: player1.publicKey.toBase58(),
    seatIndex: seatIdx1,
    maxPlayers: 5,
  }) as any;

  log(`  Response: ${JSON.stringify(createReport)}`);
  if (!createReport?.ok) fail('POST /rooms rejected', createReport);
  const { matchId, roomCode } = createReport;
  ok(`Room created: roomCode=${roomCode}, matchId=${matchId}`);

  // ── 7. deposit (Player 2 joins) ───────────────────────────────────────────

  log('\n--- Step 3: deposit (Player 2) ---');
  const seatIdx2 = 1;
  const seat2 = deriveSeatPda(pdas.matchPda, player2.publicKey);
  const seatIndex2 = deriveSeatIndexPda(pdas.matchPda, seatIdx2);

  const depositIx = buildDeposit(
    player2.publicKey, pdas.protocol, pdas.matchPda,
    seat2, seatIndex2, p2Token, pdas.vault, seatIdx2,
  );

  const depositTx = new Transaction();
  depositTx.add(depositIx as any);
  depositTx.feePayer = player2.publicKey;
  depositTx.recentBlockhash = (await conn.getLatestBlockhash()).blockhash;

  log('  Submitting deposit...');
  let depositTxSig: string;
  try {
    depositTxSig = await sendAndConfirmTransaction(conn, depositTx, [player2], {
      commitment: 'finalized',
      preflightCommitment: 'confirmed',
    });
    ok(`deposit confirmed: ${depositTxSig}`);
  } catch (e) {
    fail('deposit failed', e);
  }

  // ── 8. Report deposit txhash to matchmaking ───────────────────────────────

  log('\n--- Step 4: POST /matches/:id/deposits (report deposit) ---');
  const depositReport = await apiPost(`${MATCHMAKING_URL}/matches/${matchId}/deposits`, {
    wallet: player2.publicKey.toBase58(),
    depositTxSig,
    seatIndex: seatIdx2,
  }) as any;

  log(`  Response: ${JSON.stringify(depositReport)}`);
  if (!depositReport?.ok) fail('POST /matches/:id/deposits rejected', depositReport);
  ok(`Player 2 seated: seat=${depositReport.seat}`);

  // ── 9. GET /rooms/:roomCode — verify both players visible ─────────────────

  log('\n--- Step 5: GET /rooms/:roomCode ---');
  const lobby = await apiGet(`${MATCHMAKING_URL}/rooms/${roomCode}?wallet=${player1.publicKey.toBase58()}`) as any;
  log(`  Lobby: ${JSON.stringify(lobby?.lobby ?? lobby)}`);
  const seatedCount = lobby?.lobby?.seated ?? 0;
  if (seatedCount < 2) fail(`Expected 2 seated players, got ${seatedCount}`);
  ok(`Lobby shows ${seatedCount}/5 players seated`);

  // ── 10. Gateway WebSocket auth test (both players) ────────────────────────

  log('\n--- Step 6: Gateway WebSocket auth ---');
  try {
    await testGatewayAuth(player1, 'Player 1');
    ok('Player 1 WS auth passed');
    await testGatewayAuth(player2, 'Player 2');
    ok('Player 2 WS auth passed');
  } catch (e) {
    log(`  WS auth skipped/failed: ${(e as Error).message}`);
    log('  (this is non-fatal if gateway is only accessible from VPS localhost)');
  }

  // ── done ──────────────────────────────────────────────────────────────────

  log('\n=== E2E test PASSED ===');
  log(`Match on-chain: ${pdas.matchPda.toBase58()}`);
  log(`Room code:      ${roomCode}`);
  log(`Match ID:       ${matchId}`);
  log(`Create tx:      ${createTxSig!}`);
  log(`Deposit tx:     ${depositTxSig!}`);
  log('\nNext: wait for match to fill/lock → begin_live (backend orchestrator) → SEALING → LIVE → settle');
  log('To refund (before LIVE): solana program invoke void_before_start ...');
}

main().catch((e) => {
  console.error('Fatal:', e);
  process.exit(1);
});
